   247	\begin{lemma}[Non-encoding support estimate]
   248	\label{lem:qld-nonencoding-mass-bound}
   249		\lean{MIPStarRE.QPBT.nonencodingMarginalMass}
   250		\lean{MIPStarRE.QPBT.nonencodingMarginalMass_le}
   251		\uses{def:s-w-marginals, def:qld-full-field-decoder, def:expanded-state,
   252			lem:qld-4-7}
   253		For either player and either Pauli basis, the non-encoding marginal mass in
   254		Equation~\eqref{eq:qld-nonencoding-mass} is at most
   255		$\delta_P^{\mathrm{supp}}=C_{\mathrm{supp}}B$ for a universal
   256		$C_{\mathrm{supp}}\geq1$. This bound must be derived from point consistency and
   257		Schwartz--Zippel; it is not an additional extraction hypothesis.
   258	\end{lemma}
   259	
   260	% Following the source, the next lemma is stated after
   261	% lem:qld-construct-the-paulis, whose proof invokes it; its own proof
   262	% depends only on lem:qld-4-7 and lem:qld-comm-cons, so there is no
   263	% circularity.
   264	Lemmas~\ref{lem:qld-4-7} and~\ref{lem:qld-comm-cons} imply the following two estimates, which were used in the proof of Lemma~\ref{lem:qld-construct-the-paulis}.
   265	
   266	\begin{lemma}[The marginals absorb the point measurements]\label{lem:qld-constructing-the-paulis-helper}
   267		\lean{MIPStarRE.QPBT.sum_marginalPoly_pointMeas_approx_id}
   268		\lean{MIPStarRE.QPBT.marginalPoly_sub_pointMeas_approx_zero}
   269		\leanok
   270		\uses{def:s-w-marginals, def:expanded-point-measurement, def:expanded-state, def:povm-distance, lem:qld-4-7, def:symmetric-equivalents}
   271		For $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
   272		\begin{equation}\label{eq:qld-sg-cons}
   273			\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P^{\mathrm{id}}} \Id
   274		\end{equation}
   275		and
   276		\begin{equation}\label{eq:qld-sg-cons2}
   277			\bigl(\hat{S}^W_g \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)})\bigr)_{\mathrm{A}\mathrm{A}'} \approx_{\delta_P^{\mathrm{ann}}} 0\;,
   278		\end{equation}
   279		where the answer summation is over $g \in \mathrm{ideg}_{d,m}(\F_q)$. The independently quantified scale $\delta_P^{\mathrm{ann}}$ includes the additional point-measurement error in \eqref{eq:qld-sg-cons2}. Furthermore, all symmetric equivalents of these approximations also hold (Definition~\ref{def:symmetric-equivalents}).
   280	\end{lemma}
   281	\begin{proof}
   282		\uses{lem:qld-4-7, fact:agreement, fact:add-a-proj, def:bracket, lem:qld-comm-cons}
   283		The point-consistency conclusion of Lemma~\ref{lem:qld-4-7} states that, on average over $u \in \F_q^m$,
   284		\[
   285			\bra{\hat\psi} \sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point}, W), u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \ket{\hat\psi} \geq 1 - \delta_G\;,
   286		\]
   287		which says exactly that the operator on the left-hand side of \eqref{eq:qld-sg-cons} is $\delta_G$-consistent with $\Id$; Lemma~\ref{fact:agreement} and the universal-factor enlargement give the $\approx_{\delta_P}$ statement \eqref{eq:qld-sg-cons}. For \eqref{eq:qld-sg-cons2}, the same consistency, written with the coarse-graining $\hat{S}^W_{[g(u)=a]} = \sum_{g : g(u) = a} \hat{S}^W_g$ as $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G)} (\hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{B}\mathrm{A}''}$ with answer summation over $a \in \F_q$, is left-multiplied by $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'}$ using Lemma~\ref{fact:add-a-proj}; moving $\hat{M}^{(\mathrm{Point}, W), u}_a$ from registers $\mathrm{B}\mathrm{A}''$ to $\mathrm{A}\mathrm{A}'$ costs a further $\eps$ by Cauchy--Schwarz together with the self-consistency of the $\hat{M}^{(\mathrm{Point}, W), u}_a$ (Lemma~\ref{lem:qld-comm-cons}), giving
   288		\[
   289			(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G + \eps)} (\hat{S}^W_{[g(u)=a]} \cdot \hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{A}\mathrm{A}'}\;.
   290		\]
   291		Expanding
   292		\[
   293			\E_u \sum_g \bigl\| (\hat{S}^W_{g} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)}))_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi} \bigr\|^2
   294			= \E_u \sum_a \bra{\hat\psi} \bigl((\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a}) \cdot \hat{S}^W_{[g(u)=a]} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a})\bigr)_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi}
   295		\]
   296		and bounding the right-hand side by $O(\delta_G + \eps)$ using the two approximations above yields \eqref{eq:qld-sg-cons2} at scale $\delta_P$. The symmetric equivalents follow by the same argument with the register bipartitions interchanged.
   297	\end{proof}
