   137	structure PauliSoundnessWitness (P : AdmissibleParams)
   138	    (S : Strategy (pauliBasisTest P)) where
   139	  ιA' : Type
   140	  ιB' : Type
   141	  [ιAFintype : Fintype ιA']
   142	  [ιBFintype : Fintype ιB']
   143	  [ιADecidableEq : DecidableEq ιA']
   144	  [ιBDecidableEq : DecidableEq ιB']
   145	  φA : EuclideanSpace ℂ S.ιA →ₗᵢ[ℂ]
   146	    EuclideanSpace ℂ (ιA' × PauliRegister P)
   147	  φB : EuclideanSpace ℂ S.ιB →ₗᵢ[ℂ]
   148	    EuclideanSpace ℂ (ιB' × PauliRegister P)
   149	  aux : EuclideanSpace ℂ (ιA' × ιB')
   150	  aux_norm : ‖aux‖ = 1
