   152	attribute [instance] PauliSoundnessWitness.ιAFintype PauliSoundnessWitness.ιBFintype
   153	  PauliSoundnessWitness.ιADecidableEq PauliSoundnessWitness.ιBDecidableEq
   154	
   155	/-- The A-side operator-distance quantity appearing in the soundness
   156	conclusion.  It is the finite-sum realization of `def:povm-distance` from
   157	`blueprint/src/chapter/ch12_qpbt_games.tex:219-226`, paper origin
   158	`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:258-271`.
