   160	noncomputable def pauliOperatorDistanceA
   161	    (P : AdmissibleParams) (S : Strategy (pauliBasisTest P))
   162	    (w : PauliSoundnessWitness P S) (W : PauliKind) : ℝ :=
   163	  ∑ u : PauliRegister P,
   164	      ‖applyOperatorToState (liftedAEffect S w.φA
   165	        (((S.A (pauliQuestion P W)).postprocess pauliAnswerOrZero).effect u) -
   166	      pauliProjOnA'' P W u) (idealState P w.aux)‖ ^ 2
   167	
   168	/-- The symmetric B-side operator-distance quantity from `def:povm-distance`,
   169	blueprint `ch12_qpbt_games.tex:219-226`, paper origin
   170	`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:258-271`.
   171	-/
   172	noncomputable def pauliOperatorDistanceB
   173	    (P : AdmissibleParams) (S : Strategy (pauliBasisTest P))
   174	    (w : PauliSoundnessWitness P S) (W : PauliKind) : ℝ :=
   175	  ∑ u : PauliRegister P,
   176	      ‖applyOperatorToState (liftedBEffect S w.φB
   177	        (((S.B (pauliQuestion P W)).postprocess pauliAnswerOrZero).effect u) -
   178	      pauliProjOnB'' P W u) (idealState P w.aux)‖ ^ 2
   179	
   180	end
